#include "pch.h"
#include "CaptureNaming.h"
#include "ConfigService.h"
#include "ImageCodec.h"
namespace sct::services {
bool RenderCaptureFilename(const CString& pattern,const SYSTEMTIME& now,uint64_t counter,CString& name,CString& error){
    if(pattern.IsEmpty()||pattern.GetLength()>160||pattern.FindOneOf(L"\\/:*?\"<>|\r\n")>=0){error=L"Invalid filename pattern: no path separators or reserved filename characters";return false;}name=pattern;CString date,time,ms,sequence;date.Format(L"%04u%02u%02u",now.wYear,now.wMonth,now.wDay);time.Format(L"%02u%02u%02u",now.wHour,now.wMinute,now.wSecond);ms.Format(L"%03u",now.wMilliseconds);sequence.Format(L"%06llu",static_cast<unsigned long long>(counter));name.Replace(L"{date}",date);name.Replace(L"{time}",time);name.Replace(L"{ms}",ms);name.Replace(L"{counter}",sequence);
    if(name.FindOneOf(L"{}")>=0||name.GetLength()>220||name==L"."||name==L".."||name.Right(1)==L"."||name.Right(1)==L" "){error=L"Unknown filename token, invalid suffix or excessive length";return false;}CString stem=name.SpanExcluding(L".");stem.MakeUpper();for(const auto* reserved:{L"CON",L"PRN",L"AUX",L"NUL",L"COM1",L"COM2",L"COM3",L"COM4",L"COM5",L"COM6",L"COM7",L"COM8",L"COM9",L"LPT1",L"LPT2",L"LPT3",L"LPT4",L"LPT5",L"LPT6",L"LPT7",L"LPT8",L"LPT9"})if(stem==reserved){error=L"Reserved Windows filename";return false;}return true;
}
bool ValidateCapturePattern(const CString& pattern,CString& error){SYSTEMTIME now{2026,10,0,20,12,34,56,789};CString name;return RenderCaptureFilename(pattern,now,1,name,error);}
namespace {
bool NextCounter(uint64_t& counter,CString& error){const auto location=paths::Counter();std::error_code ec;std::filesystem::create_directories(location.parent_path(),ec);if(ec){error=L"Cannot create capture counter directory";return false;}CString path=location.c_str();HANDLE file=INVALID_HANDLE_VALUE;for(int i=0;i<30&&file==INVALID_HANDLE_VALUE;++i){file=CreateFile(path,GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE&&GetLastError()==ERROR_SHARING_VIOLATION)Sleep(10);else break;}if(file==INVALID_HANDLE_VALUE){error.Format(L"Cannot lock capture counter %s (Win32=%lu)",path.GetString(),GetLastError());return false;}struct Scope{HANDLE value;~Scope(){CloseHandle(value);}}scope{file};LARGE_INTEGER size{};DWORD got=0;uint64_t value=0;if(!GetFileSizeEx(file,&size)||(size.QuadPart!=0&&size.QuadPart!=8)||(size.QuadPart==8&&(!ReadFile(file,&value,8,&got,nullptr)||got!=8))||value==UINT64_MAX){error=L"Invalid capture counter; preserve this file for diagnosis";return false;}++value;DWORD written=0;if(SetFilePointer(file,0,nullptr,FILE_BEGIN)==INVALID_SET_FILE_POINTER||!WriteFile(file,&value,8,&written,nullptr)||written!=8||!FlushFileBuffers(file)){error=L"Cannot persist capture counter";return false;}counter=value;return true;}
}
bool SaveCapture(const core::Image& image,const Settings& settings,CString& path,CString& error){std::vector<BYTE> bytes;if(!EncodeImage(image,settings.format,settings.jpegQuality,bytes,error))return false;std::filesystem::path directory(settings.directory.GetString());if(directory.is_relative())directory=std::filesystem::path(ConfigService::ExecutableDirectory().GetString())/directory;std::filesystem::create_directories(directory);SYSTEMTIME now{};GetLocalTime(&now);for(int attempt=0;attempt<20;++attempt){uint64_t counter=0;if(!NextCounter(counter,error))return false;CString name;if(!RenderCaptureFilename(settings.filePattern,now,counter,name,error))return false;if(attempt&&settings.filePattern.Find(L"{counter}")<0){CString suffix;suffix.Format(L"_%06llu",static_cast<unsigned long long>(counter));name+=suffix;}CString candidate=(directory/(name+L"."+settings.format).GetString()).c_str();if(WriteBytes(candidate,bytes,error,false)){path=candidate;error.Empty();return true;}if(!PathFileExists(candidate))return false;}error=L"Capture filename collision retry limit";return false;}
}
